window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7510e4a057f3be16"]={"versions": [{"id": "FIG-7510e4a057f3be16", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit zahlreichen Darstellungsattributen:\n<ul class=\"fig-list\"><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Rendering-Verhalten von Dokumentationsgeneratoren. Alle Darstellungsattribute besitzen definierte Standardwerte (z. B. <code>SHOW-LONG-NAME</code>, <code>SHOW-NUMBER</code>, <code>SHOW-PAGE</code>, <code>SHOW-SHORT-NAME</code>, <code>SHOW-TYPE</code> auf sichtbar bzw. aktiv; Alias, Content, Category und See standardmäßig unterdrückt). Werkzeuge zur Dokumentgenerierung müssen diese Attribute interpretieren und die Auflösung der <code>0..1</code>-Referenz auf <code>Referrable</code> absichern.</p>"}, {"id": "FIG-7a6f6c29882aee2c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit zahlreichen Darstellungsattributen:\n<ul class=\"fig-list\"><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Rendering-Verhalten von Dokumentationsgeneratoren. Alle Darstellungsattribute besitzen definierte Standardwerte (z. B. <code>SHOW-LONG-NAME</code>, <code>SHOW-NUMBER</code>, <code>SHOW-PAGE</code>, <code>SHOW-SHORT-NAME</code>, <code>SHOW-TYPE</code> auf sichtbar bzw. aktiv; Alias, Content, Category und See standardmäßig unterdrückt). Werkzeuge zur Dokumentgenerierung müssen diese Attribute interpretieren und die Auflösung der <code>0..1</code>-Referenz auf <code>Referrable</code> absichern.</p>"}, {"id": "FIG-2b99cee74b2635f6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Auflösungs- und Rendering-Verhalten von Dokumentationsgeneratoren. Neben den Darstellungsflags definiert <code>resolutionPolicy</code> mit dem Standardwert <code>NO-SLOPPY</code> verbindlich die Strenge der Querverweisauflösung. Werkzeuge müssen fehlschlagende Referenzauflösungen gemäß der gewählten Policy behandeln und die Standardwerte für die Ausgabe von Typ, Name, Seite und Nummer anwenden.</p>"}, {"id": "FIG-0a2d5c1a6fa71010", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Auflösungs- und Rendering-Verhalten von Dokumentationsgeneratoren. Neben den Darstellungsflags definiert <code>resolutionPolicy</code> mit dem Standardwert <code>NO-SLOPPY</code> verbindlich die Strenge der Querverweisauflösung. Werkzeuge müssen fehlschlagende Referenzauflösungen gemäß der gewählten Policy behandeln und die Standardwerte für die Ausgabe von Typ, Name, Seite und Nummer anwenden.</p>"}, {"id": "FIG-e065d589a9eeed92", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Auflösungs- und Rendering-Verhalten von Dokumentationsgeneratoren. Neben den Darstellungsflags definiert <code>resolutionPolicy</code> mit dem Standardwert <code>NO-SLOPPY</code> verbindlich die Strenge der Querverweisauflösung. Werkzeuge müssen fehlschlagende Referenzauflösungen gemäß der gewählten Policy behandeln und die Standardwerte für die Ausgabe von Typ, Name, Seite und Nummer anwenden.</p>"}, {"id": "FIG-dda15faca6603619", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Attribute steuern normativ das Auflösungs- und Rendering-Verhalten von Dokumentationsgeneratoren. Neben den Darstellungsflags definiert <code>resolutionPolicy</code> mit dem Standardwert <code>NO-SLOPPY</code> verbindlich die Strenge der Querverweisauflösung. Werkzeuge müssen fehlschlagende Referenzauflösungen gemäß der gewählten Policy behandeln und die Standardwerte für die Ausgabe von Typ, Name, Seite und Nummer anwenden.</p>"}, {"id": "FIG-1d928b1c3b40db63", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>, annotiert mit dem Stereotyp <code>«atpIdentityContributor»</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert verbindlich die Identitätsbildung und Referenzauflösung: Durch die Kennzeichnung von <code>shortName</code> mit <code>«atpIdentityContributor»</code> trägt der Bezeichner normativ zur eindeutigen Pfadidentität des referenzierbaren Ziels bei. Zusammen mit <code>resolutionPolicy</code> müssen Tools die Referenzierung strikt validieren und die Dokumentgenerierung entsprechend den Darstellungsattributen ausführen.</p>"}, {"id": "FIG-bce4dc8095904046", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Generic Structure Template (AUTOSAR MSR / Generic Documentation &amp; Documentation Modeling). Das Diagramm modelliert Querverweise (<code>Xref</code>) innerhalb von Inline-Textelementen (<code>InlineTextElements</code>) auf referenzierbare Modellelemente (<code>Referrable</code>) sowie die Konfiguration ihrer Textdarstellung in generierten Dokumenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Klassen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Repräsentiert das Inline-Querverweiselement mit Attributen zur Auflösungsstrategie und Textdarstellung:\n<ul class=\"fig-list\"><li><code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code>\n</li><li><code>showContent: ShowContentEnum [0..1] = NO-SHOW-CONTENT</code>\n</li><li><code>showResourceAliasName: ShowResourceAliasNameEnum [0..1] = NO-SHOW-ALIAS</code>\n</li><li><code>showResourceCategory: ShowResourceCategoryEnum [0..1] = NO-SHOW-CATEGORY</code>\n</li><li><code>showResourceLongName: ShowResourceLongNameEnum [0..1] = SHOW-LONG-NAME</code>\n</li><li><code>showResourceNumber: ShowResourceNumberEnum [0..1] = SHOW-NUMBER</code>\n</li><li><code>showResourcePage: ShowResourcePageEnum [0..1] = SHOW-PAGE</code>\n</li><li><code>showResourceShortName: ShowResourceShortNameEnum [0..1] = SHOW-SHORT-NAME</code>\n</li><li><code>showResourceType: ShowResourceTypeEnum [0..1] = SHOW-TYPE</code>\n</li><li><code>showSee: ShowSeeEnum [0..1] = NO-SHOW-SEE</code>\n</li></ul>\n</li><li><code>Identifiable::Referrable</code>: Zielklasse der Referenzierung mit dem Attribut <code>shortName: Identifier</code>, annotiert mit dem Stereotyp <code>«atpIdentityContributor»</code>.\n</li><li><code>SingleLanguageData::SingleLanguageLongName</code> (Stereotyp <code>«atpMixedString»</code>, Paketkontext <code>MixedContentForLongName</code>): Bildet die einbettbare Bezeichnung bzw. den Bezeichnertext des Querverweises ab.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Assoziation von <code>Xref</code> nach <code>Referrable</code>: Unidirektionale Referenz mit Rollennamen <code>+referrable</code> und Multiplizität <code>0..1</code>.\n</li><li>Komposition von <code>Xref</code> nach <code>SingleLanguageLongName</code>: Komposition mit Rollennamen <code>+label1</code> und Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Ein Dokument-Generator oder MSR-Renderer wertet beim Antreffen eines <code>Xref</code>-Elements die Enums zur Darstellungsauswahl (<code>showResource...</code>) aus, löst das referenzierte Modellelement über die Assoziation <code>referrable</code> auf und formatiert den Querverweis unter Einbeziehung des optionalen Labels (<code>label1</code>) im Zieldokument.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert verbindlich die Identitätsbildung und Referenzauflösung: Durch die Kennzeichnung von <code>shortName</code> mit <code>«atpIdentityContributor»</code> trägt der Bezeichner normativ zur eindeutigen Pfadidentität des referenzierbaren Ziels bei. Zusammen mit <code>resolutionPolicy</code> müssen Tools die Referenzierung strikt validieren und die Dokumentgenerierung entsprechend den Darstellungsattributen ausführen.</p>"}], "trans": [{"from": "FIG-7510e4a057f3be16", "to": "FIG-7a6f6c29882aee2c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Formatierung/Layout: Trennlinie zwischen Klassenname und Attributbereich in <code>InlineTextElements::Xref</code> sowie Abstände um Doppelpunkte bei Attributtypen geringfügig angepasst.\n</li><li>Keine inhaltlichen Änderungen an Klassen, Attributen oder Assoziationen.\n</li></ul>"}, {"from": "FIG-7a6f6c29882aee2c", "to": "FIG-2b99cee74b2635f6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>InlineTextElements::Xref</code>: Attribut <code>resolutionPolicy: ResolutionPolicyEnum [0..1] = NO-SLOPPY</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-2b99cee74b2635f6", "to": "FIG-0a2d5c1a6fa71010", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0a2d5c1a6fa71010", "to": "FIG-e065d589a9eeed92", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Layout/Rendering: Geringfügige Anpassung der Bildabmessungen (1534x480 auf 1536x482 Pixel) und Zeichenabstände um Doppelpunkte.\n</li><li>Keine inhaltlichen Änderungen an Modellbestandteilen.\n</li></ul>"}, {"from": "FIG-e065d589a9eeed92", "to": "FIG-dda15faca6603619", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dda15faca6603619", "to": "FIG-1d928b1c3b40db63", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Identifiable::Referrable</code>: Attribut <code>shortName</code> mit dem Stereotyp <code>«atpIdentityContributor»</code> annotiert.\n</li></ul>"}, {"from": "FIG-1d928b1c3b40db63", "to": "FIG-bce4dc8095904046", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
